parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const data = payload.data?.item || payload;
  const user = data.user || data.contacts?.[0] || {};
  const conversation = data.conversation_parts?.conversation_parts?.[0] || {};

  const name = user.name || '';
  const email = user.email || '';
  const company = user.companies?.companies?.[0]?.name || '';
  const plan = user.custom_attributes?.plan || '';
  const revenue = parseFloat(user.custom_attributes?.monthly_spend || 0);
  const isHighValue = revenue > 500 || plan === 'enterprise';

  return {
    json: {
      conversationId: data.id || '',
      userId: user.id || user.user_id || '',
      name: name,
      email: email,
      company: company,
      plan: plan,
      monthlyRevenue: revenue,
      isHighValue: isHighValue,
      message: (conversation.body || data.body || '').substring(0, 500),
      source: data.source?.type || 'conversation',
      assignee: data.assignee?.name || 'Unassigned',
      tags: (data.tags?.tags || []).map(t => t.name).join(', '),
      createdAt: data.created_at ? new Date(data.created_at * 1000).toISOString() : new Date().toISOString()
    }
  };
});

